package main

import (
	"encoding/json"
	"log"
	"net/http"
	"strconv"
)

type Room struct {
	ID        int      `json:"id"`
	Name      string   `json:"name"`
	Building  string   `json:"building"`
	Capacity  int      `json:"capacity"`
	Amenities []string `json:"amenities"`
}

var rooms = map[int]Room{
	1: {ID: 1, Name: "Turing", Building: "main-library", Capacity: 6, Amenities: []string{"whiteboard", "screen"}},
	2: {ID: 2, Name: "Lovelace", Building: "main-library", Capacity: 4, Amenities: []string{"whiteboard"}},
	3: {ID: 3, Name: "Hopper", Building: "science-library", Capacity: 8, Amenities: []string{"screen", "video-call"}},
}

func getRoom(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.PathValue("roomID"))
	room, ok := rooms[id]
	if err != nil || !ok {
		http.Error(w, "room not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(room)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/rooms/{roomID}", getRoom)

	log.Println("Roombook is listening on http://localhost:8080")
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", mux))
}
